INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('26be6fe9-c3f0-4f80-8822-47dc5b8e5f92','sdt-core','Self-Determination Theory (Ryan & Deci): Humans have three innate psychological needs:
1. AUTONOMY - feeling of choice and self-direction ("I choose to do this")
2. COMPETENCE - feeling effective and capable, experiencing mastery
3. RELATEDNESS - feeling connected to others, sense of belonging
