INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('dc7c62ac-069e-498a-a7c7-0af405a18403','habit-loop-core','The Habit Loop (Charles Duhigg): Every habit follows CUE → ROUTINE → REWARD.
- CUE: Trigger that initiates behavior (location, time, emotion, people, preceding action)
- ROUTINE: The behavior itself (physical, mental, or emotional)
- REWARD: The benefit that reinforces the loop (pleasure, relief, satisfaction)
