INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('319baef7-46ad-4f37-a65f-b3308163e01c','habit-stacking','Habit Stacking: Link new habits to existing ones using: "After [CURRENT HABIT], I will [NEW HABIT]"
Examples:
- After I pour my morning coffee, I will write one sentence in my journal
- After I sit at my desk, I will write my #1 priority
- After I brush my teeth, I will meditate for 2 minutes
