INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('8a478a05-cd37-4837-8037-a8eda6334225','four-laws-core','Four Laws of Behavior Change (James Clear):
1. MAKE IT OBVIOUS (Cue) - Use implementation intentions: "I will [BEHAVIOR] at [TIME] in [LOCATION]"
2. MAKE IT ATTRACTIVE (Craving) - Temptation bundling, join supportive culture
3. MAKE IT EASY (Response) - Reduce friction, use 2-minute rule
