INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('1f77a8d2-d7b8-494a-bbdf-5aebdf891aa3','energy-patterns','Energy Patterns for Habits:
- MORNING: High cortisol, peak alertness → challenging/important tasks
- AFTERNOON: Post-lunch dip → routine/easier tasks
- EVENING: Declining willpower → easy habits, reflection
