INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('3bc72e08-4284-415a-b1c7-071b1972644b','md-bj-fogg-behavior-model-common-design-errors','Common Design Errors

1. Setting the behavior too large at the start (overestimating motivation persistence)
2. Choosing unreliable prompts (person prompts, calendar reminders, willpower)
3. Skipping celebration (emotion is what wires the habit, not repetition alone)
4. Growing the habit too fast before the anchor is solid
5. Treating motivation as character rather than fluctuating state

