INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('e652b47a-9fb4-420b-b2f3-42e7e41c8632','md-habit-loop-the-role-of-belief','The Role of Belief

Change requires belief. People with strong habits often relapse under stress unless they have a new belief system (a community, a philosophy, an identity) to support the new routine.
This is why groups and social accountability amplify habit change — they provide shared belief that change is possible even when individual motivation is low.','The Power of Habit (Charles Duhigg)','{"habit-formation","behavior-change"}','{"role","belief","change","requires","people","strong","habits","often","relapse","under","stress","unless","system","community","philosophy"}','[0.08921553,-0.00712058,-0.0282694,-0.11513306,-0.01475337,-0.11906306,0.02444243,0.16246983,0.04100215,0.00817796,-0.07221401,-0.0045922,0.02283463,0.08119873,0.11497758,0.06317467,0.00736589,0.01201355,0.02718311,-0.02738567,-0.0076052,-0.04027818,-0.03706018,0.09571771,0.02995827,-0.05347771,-0.07470974,-0.04761142,-0.05204644,-0.14376086,0.05515888,-0.07768962,-0.0406179,0.04359251,0.06635472,0.01267076,-0.0416586,-0.02968268,0.00333927,-0.05690561,0.0357384,0.03257834,-0.08801924,0.05431746,0.01955097,-0.00601189,0.04962212,-0.01651086,0.04437822,-0.04238977,0.00541722,0.07845338,0.00199419,-0.00484266,-0.1201005,-0.06755503,0.03236861,-0.02785506,-0.00751244,-0.04087884,0.03944521,-0.0427916,-0.02168593,0.02856198,0.02391493,0.06478681,0.00657076,-0.01895703,-0.09053279,-0.01479442,0.01997305,-0.06260401,-0.06804008,0.08754274,-0.02926046,0.07215252,-0.06449126,-0.00675375,-0.00291084,0.02207397,-0.0444713,0.02198378,-0.01375848,-0.00956937,-0.02969397,0.04956959,-0.01020027,0.00611949,-0.02232009,0.02027043,-0.03927578,0.02775268,-0.06076132,0.01281665,-0.02590999,-0.02835602,0.04833856,0.04997162,-0.00335978,-0.01811646,0.03704653,0.1044495,-0.02920006,0.01172089,-0.09352753,-0.05279437,0.06489136,0.04774981,0.01524131,0.01867737,-0.09377314,0.08149763,0.02868161,0.01252721,-0.01918945,0.00421875,0.02289298,-0.03168217,0.00478948,0.03067236,0.01431413,-0.01306872,-0.01261642,0.07811988,0.01950212,-0.05925792,0.00537661,-0.13010912,-0.00198128,0.03550224,0.06363978,0.02121346,0.04940565,0.05610435,-0.02078816,0.00940581,0.04379097,-0.0039552,0.04614635,-0.04132015,-0.02422749,-0.053