INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('5358cc0d-163a-4180-93ee-90360aefa451','md-neuroscience-habits-key-brain-structures','Key Brain Structures

### Basal Ganglia
- Central hub for habit formation
- Stores automated behavioral patterns
- Takes over from conscious control as habit forms
- Includes: striatum, caudate nucleus, putamen

### Prefrontal Cortex
- Executive function and conscious decision-making
- Active when learning new behaviors
- Activity decreases as behavior becomes habitual
- "Hands off" control to basal ganglia over time

### Striatum
- Links environmental cues to motor responses
- Encodes the cue-response relationship
- Key for "chunking" behaviors into routines

### Dopamine System
- Reward encoding and reinforcement
- Signals value of outcomes
- Key regions: ventral tegmental area, substantia nigra
- Each successful habit execution = dopamine release','Neuroscience of Habit Formation','{"neuroscience","habit-formation"}','{"brain","structures","basal","ganglia","central","habit","formation","stores","automated","behavioral","patterns","takes","over","conscious","control"}','[0.04659383,-0.02864893,-0.00291199,-0.01202735,0.00855578,-0.01395587,0.02181348,-0.07559697,0.02161195,-0.09718468,-0.15014029,0.03162359,-0.05549796,0.21026252,0.08957125,-0.02619192,-0.04542371,-0.10437523,0.0552839,0.04197899,-0.00641318,0.01757305,-0.04908023,0.10883912,0.00788314,0.02194312,0.07683385,-0.05695906,-0.03518566,-0.09806338,0.11746081,-0.02789395,-0.0075283,0.10719599,-0.01142242,-0.02482312,0.03850412,0.01099952,0.02676851,-0.06023835,-0.00036505,-0.00609761,-0.10605407,-0.00746564,-0.00275004,-0.01608998,0.11397652,-0.01020687,0.02309556,-0.06538349,0.0375772,0.09959971,-0.01787551,-0.0274932,-0.00516055,0.10782395,0.03927639,-0.00999261,-0.0104042,-0.03020468,-0.03136588,0.00909285,0.01162181,-0.01324777,0.02016977,-0.03303035,0.02044119,0.00760051,-0.12481271,0.04704842,0.09685267,-0.02987098,-0.01278018,-0.01155422,-0.09282044,-0.04749817,-0.04409436,0.06640009,-0.03483032,-0.01296021,-0.02310922,0.00630942,0.03167353,-0.01109135,-0.06526158,0.0425641,-0.10194708,0.00721411,-0.0123174,-0.01167643,-0.09598956,-0.07771291,-0.01442006,-0.01230481,-0.03547269,-0.03810756,0.04004898,-0.05294339,-0.01660603,-0.02725565,-0.01441983,0.04114904,-0.01449964,0.00973062,0.06204447,-0.02960163,0.01735494,0.01970005,-0.00085831,0.0050743,0.005704,0.03024137,0.00146609,-0.00213381,-0.03805513,0.04978639,0.03169896,-0.06288829,-0.066632,0.01973513,-0.00433257,-0.08293346,0.05898279,0.09484646,-0.02098653,-0.0815292,0.02136272,-0.0446865,-0.01503111,0.07854806,-0.04038522,-0.01276011,0.07654081,0.0893152,-0.09647767,0.04107303,0.00109115,0.06167245,0.00877036,0.00516969,0.04733597,0.00678675,-0.05927003,0.00455581,-0.00555013,0.00273111,-0.00190989,0.025716,-0.06001496,0.01104752,0.