INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('abae73f7-9d78-472f-bbe0-d5040d067162','md-neuroscience-habits-key-insights-for-ai-coaching','Key Insights for AI Coaching

1. **Dopamine anticipation**: Create anticipation of reward, not just reward itself
2. **Sleep messaging**: Remind users that sleep consolidates their progress
3. **Exercise connection**: Link physical activity to mental/habit benefits
4. **Patience framing**: Neural change takes time - set expectations
5. **Stress awareness**: High stress can reactivate old patterns - be supportive
6. **Morning priming**: Encourage morning light and movement for optimal brain state','Neuroscience of Habit Formation','{"neuroscience","habit-formation"}','{"insights","coaching","dopamine","anticipation","create","reward","just","itself","sleep","messaging","remind","users","consolidates","progress","exercise"}','[0.12667204,-0.10987234,0.0517947,0.00709376,0.09182779,-0.08209758,-0.03508462,0.01907081,0.00745007,-0.13284959,-0.05190269,-0.06712237,-0.00175304,0.0717077,0.0973583,0.11572766,-0.00062711,-0.05233724,-0.02667859,-0.07544633,-0.13501619,-0.05768768,-0.02912007,0.1102369,-0.06278833,-0.02949603,0.02430937,-0.07139033,-0.01572527,-0.06948376,0.05443048,-0.04301771,-0.05601839,0.11494154,0.04917944,-0.01580524,0.07099786,0.00703859,-0.05291249,0.01251453,-0.03093062,0.00832711,-0.00397097,-0.00773384,0.0596244,0.09832584,-0.00192185,0.0096532,-0.00467074,-0.10925381,-0.00337799,0.08181509,-0.07244598,0.02784171,-0.07172119,0.04342541,0.10552707,0.06309377,0.04007904,-0.02576485,-0.03842667,-0.05531412,0.00799653,-0.01099604,-0.0083742,0.0445173,-0.07030401,-0.05266581,-0.02098592,-0.03375584,0.02709246,0.00845831,0.01819615,0.05121375,-0.01848588,-0.00143173,-0.02433061,0.03530885,0.02595761,0.00552998,-0.06495254,-0.03243481,0.02521259,0.02896491,-0.03791631,-0.00821672,-0.07605783,0.0119655,-0.00482987,-0.02251573,-0.04671849,-0.05213539,0.04346296,-0.12578572,0.03172136,-0.10168371,0.01818951,-0.01241675,-0.05844306,-0.01962147,0.01527762,0.00404471,-0.05339929,0.00220645,0.03859081,0.01528685,0.03934155,0.04733947,-0.03579111,0.01010397,0.01131971,0.04504711,0.05336501,0.01409224,0.00449587,0.05115252,0.05292486,0.00429835,0.00624124,0.03269912,0.02719707,0.0282463,0.02465918,0.00901407,0.04215108,0.06250541,0.01753349,-0.01489772,-0.03916463,-0.03396788,-0.08350483,0.03372116,-0.01678707,-0.01758496,-0.01544756,0.02581644,-0.01009336,0.0050766,0.02090749,0.02588051,0.02145732,-0.05424853,0.0281811,0.00248631,-0.02489121,-0.01404382,0.03321194,0.063