INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('d176db55-e1a0-4daf-9c78-dd370a616f46','md-neuroscience-habits-breaking-bad-habits-neural-perspective','Breaking Bad Habits (Neural Perspective)

### Why It''s Hard
- Neural pathways don''t disappear
- Old patterns remain dormant
- Stress/tiredness can reactivate them
- Must build stronger competing pathways

### Strategy
1. Don''t try to "delete" old habit
2. Build new pathway that''s stronger
3. Avoid triggers when possible
4. Use conscious override (prefrontal) initially
5. Eventually new pathway becomes dominant','Neuroscience of Habit Formation','{"neuroscience","habit-formation"}','{"breaking","habits","neural","perspective","it''s","hard","pathways","don''t","disappear","patterns","remain","dormant","stress","tiredness","reactivate"}','[0.02737317,-0.0351764,-0.0816052,-0.04738206,0.00647414,0.02614299,0.07341581,0.12200956,-0.0485968,-0.04518372,-0.10113718,-0.01825443,-0.06151929,0.13540646,0.17125985,-0.00172681,0.01872141,-0.00654583,-0.02275406,0.06659678,-0.00352574,-0.04352478,-0.0816334,0.06606393,0.01741074,-0.04780347,0.00342696,-0.1229014,-0.08790994,-0.08253677,0.07989483,0.01332042,-0.05020501,0.03173448,0.03195449,-0.0003351,0.03624852,0.07335576,0.04936892,-0.01543546,0.02115075,0.08292793,-0.03847879,-0.07614858,-0.01498326,0.01400603,0.07812309,-0.02948962,0.0448308,-0.04482108,0.01559789,0.10389723,-5.839e-05,-0.09565706,-0.06624518,0.01266614,0.05471688,-0.01386818,0.07010359,-0.01320893,-0.02868846,0.00057101,0.02267922,0.06897651,-0.02387787,-0.00588547,0.01385524,0.00598004,-0.04539537,0.0220816,-0.02282983,0.0227679,0.03709703,-0.05406108,-0.01038274,0.03275103,-0.02039497,-0.01905301,-0.05998889,0.01053125,-0.0216922,0.00882382,0.12140338,0.00105997,-0.00779215,0.05192444,-0.09010718,-0.03362445,0.01779727,-0.01188113,-0.02387878,0.02816143,-0.0951522,-0.04624007,-0.02577822,-0.06338955,-0.02647206,-0.07137387,-0.09345684,-0.02714127,0.01913261,0.00721949,-0.06407752,-0.01680719,0.03848251,-0.03472178,0.03401412,0.00864447,0.01873984,-0.06516378,-0.02364738,0.07752441,0.04736595,-0.04751227,-0.0129196,0.01036268,0.0299535,-0.04389269,-0.04185743,0.02704395,-0.01872735,-0.04847853,0.07144585,0.05103669,0.02603319,-0.09811666,0.07791028,-0.08164008,-0.02430437,0.03591144,0.02935784,-0.02393323,0.02373767,0.0469218,-0.05396989,0.02660143,-0.00134107,0.00254,0.02193525,0.00581376,-0.03865637,-0.03519833,0.00414942,-0.00240222,-0.04217578,-0.01890016,-0.00866373,0.03773955,-0.00116578,0.03153473,-0.00638357,-0