INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('47d48f39-fbcf-4358-ac17-88962eda6960','md-neuroscience-habits-exercise-and-the-brain','Exercise and the Brain

### Benefits for Habit Formation
1. Increases BDNF production
2. Grows hippocampus (memory center)
3. Improves prefrontal cortex function
4. Enhances mood and motivation
5. Creates a "keystone habit" effect

### Minimum Effective Dose
- 20-30 minutes of moderate activity
- Can be walking, not just intense exercise
- Consistency matters more than intensity','Neuroscience of Habit Formation','{"neuroscience","habit-formation"}','{"exercise","brain","benefits","habit","formation","increases","bdnf","production","grows","hippocampus","memory","center","improves","prefrontal","cortex"}','[0.02615284,-0.0118238,-0.06119408,-0.00161091,0.01986007,-0.04354766,-0.04327129,-0.01611589,0.06801578,-0.07648167,-0.07571344,-0.03062382,-0.05119354,0.03683381,0.09808687,0.0072361,0.08522778,-0.09237874,0.01476376,0.0089726,-0.04518562,-0.05232512,-0.04187055,0.17924142,-0.01958553,-0.03717998,-0.0085387,-0.15644641,-0.05850084,-0.13039733,-0.04612919,0.00684887,-0.03746366,0.10244902,0.05716191,0.02813776,0.04501133,-0.00704916,0.0078581,-0.0443219,-0.02832541,0.02605502,-0.00806466,0.05115294,0.02873464,0.06188632,0.06255592,-0.03952486,0.05449015,-0.01894557,0.00165495,0.08497594,0.04594039,0.04258269,0.01799401,0.01162964,0.04507879,0.0392602,0.04421284,-0.04662546,0.03476902,-0.01813204,-0.06057965,0.00052629,-0.03221073,-0.03300871,0.05560619,-0.01417447,-0.04375423,-0.03836487,0.07890191,-0.06641035,0.08130172,0.00261476,0.00921254,0.04078257,-0.06038473,0.00476479,0.0496118,0.06935393,-0.0439512,-0.03887039,0.02111015,-0.04947582,-0.02876533,-0.01218181,-0.04645924,0.08623224,-0.0053166,-0.04147786,-0.10235274,-0.0690635,-0.0129868,-0.04226721,-0.00864511,-0.01112424,0.03458706,-0.00419756,-0.05525421,0.04976824,-0.00289814,0.08435064,-0.00543516,0.02769035,-0.03502763,-0.03619243,0.06994123,0.05616622,0.00354565,0.01203542,0.01215165,0.01299614,-0.01937809,0.04310018,-0.00457409,0.04399769,0.01525451,-0.0632427,-0.15260108,-0.05917734,-0.07132421,-0.04094288,0.08229558,0.03887114,0.06838324,0.01418131,0.04488814,-0.04039974,-0.01626621,0.00744897,0.0243073,0.0323039,0.05040755,0.04333651,0.01290001,0.00683173,0.01979587,0.10317405,-0.00890074,0.05939634,0.01074634,-0.01288866,-0.01911007,0.01411059,-0.02169817,0.01012497,-0.00959942,0.06119915,-0.03266934,-0.06017264,-0.01178067,0.01