INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('bf8843af-b3bc-467d-94b5-baecc2380749','md-self-efficacy-bandura-self-efficacy-and-recovery-from-setbacks','Self-Efficacy and Recovery from Setbacks

High-efficacy people attribute failure to insufficient effort or inappropriate strategy (modifiable) and increase effort and adjust strategy. Low-efficacy people attribute failure to personal deficiency (stable, unmodifiable) and decrease effort or quit.

Coaching during failure: always attribute to strategy or effort (controllable), never to ability (fixed). "That approach didn''''t work" is better than "That was too hard for where you are."','self-efficacy-bandura','{"habit-formation"}','{"self-efficacy","recovery","setbacks","high-efficacy","people","attribute","failure","insufficient","effort","inappropriate","strategy","modifiable","increase","adjust","low-efficacy"}','[0.03561112,-0.05151527,-0.06861673,-0.05689149,-0.03977595,-0.05166379,-0.03764426,0.12124901,-0.02601894,-0.02158009,-0.04092016,-0.07864995,-0.0023598,-0.02288539,0.21878254,0.1507601,-0.00335355,0.02879892,-0.05790186,0.03378047,-0.05150747,0.05177426,0.04113546,0.05008228,-0.06800534,-0.08878399,-0.02502617,-0.01322154,-0.05751748,-0.04072809,0.09674992,-0.01487698,-0.02089344,0.12277592,0.03129624,-0.04172021,0.0123573,0.02131508,-0.02704985,0.02340912,-0.02339231,0.10465098,0.02972132,-0.03153481,0.03234286,0.05000564,0.07399864,-0.03276766,-0.04866206,-0.02796742,0.01031864,0.03922034,-0.01307295,0.07929355,-0.09329813,-0.06709611,-0.00218961,-0.0128475,-0.05172693,0.00331481,0.04735895,-0.00534737,-0.04404807,0.00047375,-0.0065143,-0.01694858,0.02442731,-0.03942567,-0.0713606,-0.04078396,0.02852223,0.01635643,0.00177825,0.03362267,-0.01875615,0.05950079,-0.01698133,-0.04343113,0.05198605,0.00571376,-0.1007989,-0.01860135,0.0148061,0.04310163,0.00416773,0.01648758,0.00295397,-0.00798954,-0.05589703,-0.02966553,-0.04816853,0.00967352,-0.06190073,-0.04964493,0.05026937,0.0197242,-0.01973457,0.00848796,0.08233041,0.00034607,-0.00830453,0.04310377,-0.0312915,-0.0453174,0.00601414,0.04865764,-0.05169296,-0.04862329,-0.01362213,0.077741,-0.00539355,0.0457435,-0.04409381,0.02407991,-0.02440487,0.03271738,0.03021374,-0.03300916,0.04797063,0.06231358,-0.00202669,0.01870685,-0.01197625,0.11761665,0.01882288,-0.01960299,0.03509932,0.06395083,0.01518354,0.01319477,0.0123196,-0.02679309,-0.01137327,0.00699266,0.02045465,0.04546583,0.06719367,0.006738,0