INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('0851423a-3170-485e-8a4a-ef6febd85bd9','md-self-efficacy-bandura-efficacy-beliefs-vs-outcome-expectations','Efficacy Beliefs vs. Outcome Expectations

Self-efficacy is about "Can I do this?" Outcome expectation is about "Will doing this produce the result I want?" Both must be positive for action. A person can believe they can write every day (high efficacy) but doubt that writing will lead to publication (low outcome expectation). The intervention targets differ: efficacy → capability building; outcome expectation → evidence for the value of the behavior.','self-efficacy-bandura','{"habit-formation"}','{"efficacy","beliefs","outcome","expectations","self-efficacy","about","expectation","doing","produce","result","want","both","must","positive","action"}','[0.03195745,-0.05395192,-0.02412824,-0.06670143,0.01628318,-0.04773277,-0.00214731,0.06394003,0.05033658,-0.02926401,-0.03418336,-0.03731505,0.02116035,-0.10386802,0.12063089,0.14399034,0.04023873,0.06406182,-0.00209351,-0.0830581,-0.04774376,0.04786614,0.00997681,0.09936423,-0.07976543,-0.01979246,-0.03341583,-0.06263836,-0.06478543,-0.09162579,0.00038237,-0.11142489,0.04776623,0.11335482,0.02716284,-0.0289872,-0.0161075,-0.00386154,-0.04286971,0.01176041,-0.02549559,0.17380972,0.07792863,0.05515274,0.0448231,0.03286566,0.01818568,0.0065617,-0.03607435,0.06198132,0.07260682,0.04383555,-0.04011758,0.12480336,-0.05708969,0.02874129,-0.04186553,0.03102336,0.00357714,-0.01165731,0.04688315,0.00808922,-0.00555791,-0.0525902,0.0431796,-0.04098012,0.02563808,0.06262268,-0.04840513,-0.03906036,0.04334979,-0.0004711,-0.08666058,0.02153508,-0.01198955,0.04334436,-0.05214788,-0.10267001,0.0335537,0.03354651,-0.06296185,-0.03509046,-0.02710337,-0.02396337,-0.00544486,-0.03580889,0.00930027,-0.00204053,0.01771946,-0.05735404,-0.09047996,-0.03435821,-0.04960794,-0.02873391,-0.01361042,0.00850545,0.0186583,0.05120996,0.057067,0.03558518,0.03214089,0.04930399,-0.02555677,0.02480562,-0.03711224,0.07777654,-0.00429175,-0.03734582,-0.07852904,0.01070381,0.01697609,0.04588526,-0.03175803,0.0462239,-0.01807288,0.00303552,-0.00516044,-0.04844104,-0.02283849,0.01868599,-0.04649099,0.