INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('f2a50796-625d-4698-987d-ba841289a65e','md-self-determination-theory-intrinsic-vs-extrinsic-motivation','Intrinsic vs. Extrinsic Motivation

Intrinsic motivation (doing something because it is inherently interesting or satisfying) is more durable and associated with greater creativity and deeper learning.
Extrinsic motivation (doing something for a reward, grade, or to avoid punishment) can undermine intrinsic motivation if applied to activities that were previously intrinsically motivated — the "overjustification effect."
The goal of great coaching is to help users find intrinsic reasons to continue (growth, mastery, identity) rather than relying on external rewards (streaks, badges, points) that fade.','Self-Determination Theory (Ryan & Deci)','{"motivation","behavior-change"}','{"intrinsic","extrinsic","motivation","doing","something","because","inherently","interesting","satisfying","more","durable","associated","greater","creativity","deeper"}','[-0.00042591,-0.04165339,0.01225523,-0.09818257,0.02572343,0.00223649,-0.09304722,0.04887915,0.06564851,-0.01413153,-0.08145068,0.00022744,0.00322387,-0.02747357,0.13834408,0.12097313,0.02554483,0.03251266,0.00668671,-0.05066659,-0.05471002,0.01766301,0.00320318,0.12759331,0.0114154,0.00585716,0.09051152,-0.05337043,0.03698603,-0.12478112,0.04022666,0.00888229,-0.06177909,0.05702157,0.04385161,-0.03998641,0.03619804,0.04882798,-0.07317994,0.06934384,-0.04332627,0.03458452,-0.048361,-0.01169043,0.01862244,0.07029505,-0.04123139,0.0048659,0.01472081,-0.02350271,-0.01752144,0.05512513,-0.06221082,-0.0683516,0.02887608,0.07058977,0.04711401,0.05959945,0.00796674,-0.03489218,0.11688904,-0.06338505,-0.06384201,-0.00656015,-0.04057197,-0.00360621,0.00598023,-0.02468491,-0.04730811,-0.02715277,-0.03916154,-0.01189659,0.03539808,-0.02274674,0.02380819,0.04426761,-0.07947443,-0.05540724,-0.02663591,0.00105589,-0.03178022,-0.02016438,-0.03744436,-0.01096472,-0.07273622,0.02446932,-0.05528493,0.01271314,-0.01883037,0.00296905,-0.11786508,-0.01589216,-0.08027222,-0.1018277,-0.00787725,-0.10109907,0.05948047,0.04420892,-0.03515588,0.01314327,0.00451783,0.03172866,0.00099819,-0.02208216,-0.06673717,-0.02401855,0.01081267,0.0596976,-0.01873532,0.02934742,0.0157656,0.04170506,0.09506211,0.02384079,-0.02393126,0.00471419,-0.00369116,-0.0059365,-0.0406735,0.018135,0.01188958,0.04997727,-0.03452034,0.06312191,0.02231024,0.03343497,0.04499738,-0.04113159,-0.07893729,-0.01994668,-0.03316634,-0.01482438,0.0408753,-0.01767505,-0.00972276,0.03632676,-0.0072043,0.