INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('0d166337-ec27-423f-bc47-d9fbde49d7d3','md-skill-development-deliberate-practice-principles-applied-to-careers','Deliberate Practice Principles Applied to Careers

- Identify specific sub-skills within your target skill
- Practice the weakest sub-skill, not the comfortable ones
- Get feedback within 24 hours of the practice session (not at the end of the month)
- Push to the edge of your ability — not so hard you''re lost, not so easy you''re coasting
