INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('fc76aea1-3f56-4a8e-9654-1c81ba248af2','md-fear-of-failure-protocols-the-experiment-frame-in-curriculum-design','The Experiment Frame in Curriculum Design

Every task for fear-of-failure users should be framed as:
- "Experiment" not "performance"
- "Practice session" not "assessment"
- "Draft" not "final version"
- "Try it and see what happens" not "do it correctly"

Success criteria must be observation-based, not quality-based:
- Bad: "Do 10 push-ups with correct form"
- Good: "Attempt 10 push-ups and notice what feels hard — there''''s no wrong answer"
- The goal is to complete the reps, not to perform them well (performance comes later)','Coheren Coaching KB — Fear of Failure','{"coaching","behavior-change"}','{"experiment","frame","curriculum","design","every","task","fear-of-failure","users","framed","performance","practice","session","assessment","draft","final"}','[0.0624234,-0.03275871,0.13709421,0.09328917,-0.02944692,-0.06597083,-0.08601318,0.00381043,0.03777792,0.01165734,-0.08246548,0.0059755,0.01385075,-0.02784529,0.1618966,0.09830244,0.05419889,0.01561836,0.0494447,-0.02674141,-0.06942271,0.03269073,0.02714668,0.05234779,0.0405197,0.00941078,-0.08016597,-0.01581677,0.00135135,-0.01497097,0.03824529,0.04724232,0.00296455,0.05386769,0.02861065,-0.05533287,0.05712134,0.01407613,-0.00076731,-0.01951563,-0.12888084,0.03236111,0.11793742,0.08411869,-0.01787632,-0.03010948,0.03242664,0.0343463,-0.00150146,0.02134672,0.0058057,0.1235497,-0.01658549,0.06263264,0.03795601,0.0027557,0.10893431,-0.05683893,0.06329938,0.01781794,0.01180245,-0.06264915,0.08541062,0.02220915,0.00185024,-0.09110116,-0.06739216,0.01908386,-0.05386142,-0.03740327,-0.00631734,0.02860918,-0.00980028,-0.01208381,0.05705856,0.03854813,-0.06456079,-0.03885964,-0.03588583,-0.01899691,-0.04975101,-0.01586053,0.09459932,-0.01035573,-0.00741196,0.0162422,-0.08913993,-0.00945152,0.02541433,0.07278289,-0.01009929,0.01955399,0.02736662,-0.05206241,-0.04832364,0.01975727,0.03346741,-0.06827556,0.00882708,0.02056156,0.01844176,0.03129602,-0.01155898,-0.06361841,0.03562478,0.04896746,0.04787908,-0.09156315,-0.01096693,-0.04406763,-0.05573963,0.00156298,-0.030565,-0.02798072,0.02190694,0.11485234,0.02508703,-0.00064271,-0.00607783,0.03654163,0.01668609,0.0227037,0.0214826,0.04097915,-0.0544917,-0.01106018,-0.01409862,0.02521458,0.00349756,0.05375185,0.00792333,-0.0565819,0.02055003,-0.01337533,0.02361788,0.04658535,0.01140675,0.0266479,-0.01751723,0.00134974,0.01536607,-0.02593828,0.08921147,-0.00555673,-0.00151737,0.06360222,0.01182191,0.05181331,-0.0