INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('0440b77a-435c-4f62-b42c-b0109acec780','md-language-learning-common-pitfalls','Common Pitfalls

- Perfectionism: Output errors are how the brain calibrates. Speak before you feel ready.
- Single-method trap: Anki + duolingo + textbook alone never produces fluency. You need comprehensible input (real content).
- Plateau at B1: Very common. The fix is more volume of authentic content, not more grammar study.
- Speaking anxiety: Fear of making mistakes is the #1 predictor of failure. Every fluent speaker made thousands of errors first.','Coheren Domain KB — Language Learning','{"skill-progression","cognitive"}','{"common","pitfalls","perfectionism","output","errors","brain","calibrates","speak","before","feel","ready","single-method","trap","anki","duolingo"}','[0.04920806,-0.08700529,0.06735666,-0.01457178,0.00975351,0.04322721,-0.07745099,0.09527006,-0.04394976,-0.03119456,-0.06789586,-0.11112931,0.02115457,-0.0307005,0.14019164,0.04146206,-0.01961582,0.00320233,-0.1469176,0.09649115,-0.07420871,0.09050017,0.00366534,-0.00883127,-0.03466399,-0.06726541,0.06132545,-0.02226773,-0.04568539,-0.00174511,0.03264074,-0.03784342,-0.11766448,0.10740632,-0.03912676,-0.06110453,0.10871534,0.05007208,0.00107604,0.07824486,0.05484544,0.05303558,0.00788066,0.01429338,0.02732429,0.02463891,0.08122418,0.01257798,0.06003192,-0.06932746,-0.04839842,0.05365587,-0.0376279,0.01063135,-0.01527967,0.01561007,0.02611436,0.04757815,0.07423567,0.00246094,-0.06406005,0.11145451,0.03722339,-0.00697513,-0.05636372,-0.02108032,-0.00337656,-0.04835347,-0.0635339,-0.04898014,0.08544222,0.04484707,0.00780064,0.02973329,0.00091449,-0.05071156,-0.00351651,-0.02788265,0.0630858,0.00368843,-0.0171578,-0.05521988,0.09013808,-0.0179309,0.06250921,-0.03482645,0.02415224,0.00333305,0.01428688,0.07557995,-0.03797377,-0.02278104,0.03928203,-0.02436066,-0.0760022,0.00936209,-0.04350219,-0.06289868,0.1403957,-0.04100421,0.00516114,-0.03290885,-0.07219131,-0.07705405,0.03223189,-0.04446482,0.022837,-0.04538551,-0.00678102,-0.00334542,-0.07270122,0.00989266,0.00549752,-0.03214066,0.00571688,-0.00396373,0.07621917,-0.05504018,0.01000358,-0.01312019,-0.09083157,-0.02144884,-0.00397217,0.01676617,0.02557703,-0.01618426,-0.03821982,-0.05837994,0.00396845,0.0227881,-0.03356263,0.02807164,-0.01168395,0.02267236,0.01027867,-0.04434536,-0.0001466,-0.02960111,0.03530066,0.02557465,-0.0256959,0.03071717,0.01910695,-0.0409123