INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('7547960e-599a-4b1b-997a-97dab3d55d71','md-writing-common-pitfalls','Common Pitfalls

- Editing while drafting: destroys momentum and trains self-censorship
- Waiting for inspiration: professional writers write on schedule, not on inspiration
- Perfectionism before sharing: no piece is ever finished, only abandoned (Paul Valéry). Share before perfect.
- Isolation: writing benefits enormously from community — other writers are your best resource','Coheren Domain KB — Writing','{"skill-progression","creative"}','{"common","pitfalls","editing","while","drafting","destroys","momentum","trains","self-censorship","waiting","inspiration","professional","writers","write","schedule"}','[0.07868291,-0.03955717,0.07903477,-0.0426993,-0.07478661,0.10208946,-0.05295973,0.08159188,0.07230121,0.04799473,-0.07078745,-0.07520585,-0.01456985,0.027809,0.09458227,0.07589006,0.05090365,0.01211964,-0.0081491,-0.01027367,-0.01480863,0.06506695,-0.00806949,0.02747068,-0.02356338,-0.11387744,-0.0254277,-0.10286514,-0.04512232,-0.00206435,0.09145661,0.03532477,-0.06567023,0.01670667,0.01322633,0.01756333,0.06345751,0.07603811,0.02312087,0.03760482,0.02686168,0.06819325,0.06840841,-0.01504626,-0.02235226,-0.04992964,0.07943749,0.00682618,-0.03301679,-0.08299061,-0.07106216,-0.02561009,-0.00840349,-0.05060169,-0.02492436,0.03483804,0.05095027,0.03239043,0.09635867,-0.03091037,-0.08015635,0.01464171,0.00945714,-0.01701257,-0.01521173,-0.07148574,-0.00580942,-0.00071797,-0.0812832,-0.00093915,0.07238755,0.13789836,0.0493742,-0.03646886,0.01666967,-0.04266852,-0.00809782,-0.08690208,0.00709309,0.02404157,-0.05754065,-0.00409218,0.06232957,-0.03419934,0.09483436,-0.01521928,-0.03135749,0.01004008,0.03778507,0.06506762,-0.0060635,-0.01967783,0.01050249,-0.02427078,0.01464993,0.05651596,0.00445069,0.02757242,0.03682358,-0.01614362,-0.00721126,-0.03781211,-0.01031131,-0.01583611,0.08634129,0.073075,0.06689006,0.00103716,0.01021585,-0.00728995,-0.01779406,0.0213732,0.05146803,-0.10187347,-0.03913441,-0.02488931,0.02119139,-0.04237263,0.02579109,-0.00329439,-0.04271998,0.05222504,0.02354491,-0.00665107,0.06463066,-0.08888434,-0.02567447,-0.03886037,-0.00823371,0.00947648,-0.02601955,0.00476057,-0.02678387,0.05599144,-0.02302296,-0.01169312,-0.06492999,-0.04095874,-0.00921412,-0.00059968,-0.0414579,-0.01837241,0.05496675,-0.09272976,-0.04631725,-0.06