INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('3f367b7c-df5c-4196-a4aa-bf976102eed4','md-budgeting-common-pitfalls','Common Pitfalls

- Budgeting without tracking: Creating a budget without reviewing actuals weekly is wishful thinking
- Undercounting irregular expenses: Car repairs, medical bills, and home maintenance always happen — plan for them
