INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('5646ca7d-9940-4493-985d-cff840647b19','md-mental-health-common-pitfalls','Common Pitfalls

- Waiting until crisis: mental health practices are most effective as prevention, not rescue
- Avoiding discomfort: chronic avoidance of difficult emotions increases their power
- Social media as connection substitute: passive consumption of social media is not social connection — it often increases loneliness
- Inconsistency: daily practices work through accumulation. Missing 3 of 7 days halves the effect.','Coheren Domain KB — Mental Health','{"skill-progression","health"}','{"common","pitfalls","waiting","until","crisis","mental","health","practices","most","effective","prevention","rescue","avoiding","discomfort","chronic"}','[0.04352113,-0.00101392,-0.01788802,-0.06922805,0.03771021,-0.04358415,-0.04148369,0.10182971,-0.05869907,0.01875792,-0.05436067,-0.07633655,0.06959655,0.03605241,0.1780823,0.03605914,0.03439242,0.00307856,0.03265665,0.03071262,0.02226354,-0.00921823,-0.01742751,0.00169308,-0.02584242,-0.0705317,-0.10107517,-0.05100833,-0.17008567,-0.06271192,0.12472187,-0.11372759,-0.04791342,0.01077095,0.09824277,0.04117901,0.0326303,0.06234745,0.03973969,0.00230317,-0.04130675,0.07821576,-0.00226538,0.04027634,0.02236758,0.01788424,0.06523674,-0.04637133,-0.00139927,-0.06469652,-0.02000606,0.04204656,-0.00507589,0.03815847,-0.01570078,-0.01820392,0.05391521,0.04977759,0.05365426,-0.00963086,0.01650662,0.05120141,0.00950179,0.0055463,0.02177745,-0.03383796,-0.04744423,-0.00868545,-0.06607687,0.03675579,0.04594038,0.06458869,0.06765145,-0.00231555,0.01948469,0.01179114,0.0187246,-0.07643752,0.0046216,0.06919435,-0.03047222,-0.02531819,0.11518545,-0.03488346,-0.01388361,0.04358682,-0.04979137,0.04589348,-0.01457977,0.03132556,-0.03634929,-0.03018916,-0.12330283,0.00590648,0.03632035,-0.00269631,-0.00221908,-0.00264451,0.06262512,-0.01361401,0.0119976,0.01007042,-0.03425241,-0.02316161,-0.00833953,0.04419965,0.08662685,0.00125183,0.03259367,0.02548784,-0.02940317,-0.01147227,0.01011463,-0.08540622,-0.05243266,-0.03682461,0.02768971,-0.03589147,-0.02186964,0.00900062,-0.07543956,-0.03398545,-0.00081269,0.05760667,0.07913675,0.02028903,-0.04260162,-0.0362829,-0.00577342,0.06380538,-0.04723346,-0.00802417,-0.00409164,0.05959747,0.01420004,0.01335532,-0.01178851,-0.0206117,0.03740744,-0.02479569,-0.07224376,0.01375567,0.03184303,-0.06665578,-0.05743105,-0.08729216,-0.