INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('d350467d-d4d6-4f8b-a3ba-9533e1134310','md-sleep-common-pitfalls','Common Pitfalls

- Weekend sleep schedule variability: sleeping 2+ hours later on weekends is called "social jet lag" — undoes the entire week''s circadian work
- Over-reliance on supplements: sleep hygiene matters 10x more than any supplement
- Tracking-induced anxiety: obsessing over Oura/Garmin scores worsens sleep. Use data for trends, not judgment.
- Giving up after 3 days: circadian rhythm takes 1-2 weeks to shift. Changes won''t feel immediate.','Coheren Domain KB — Sleep Optimization','{"skill-progression","health"}','{"common","pitfalls","weekend","sleep","schedule","variability","sleeping","hours","later","weekends","called","social","undoes","entire","week''s"}','[-0.00942049,0.03829462,-0.09847269,-0.00767029,0.04751822,-0.02551133,-0.16716947,0.1124356,0.01069244,-0.12361204,-0.04845625,-0.11330199,-0.04228945,0.01629646,0.02531599,-0.0155919,0.04228194,-0.03662676,0.03149206,-0.01280835,-0.02545985,-0.02485729,-0.06130527,0.13385423,-0.00731658,0.04693739,0.00271356,-0.06404245,-0.0127155,-0.00564407,0.02329441,-0.10623508,-0.03061241,-0.06072405,-0.00200879,0.0639253,0.07549766,0.08068065,0.10664397,-0.05690949,0.02561388,0.03100788,-0.05079829,-0.03344433,0.02701064,-0.00568297,0.06161016,0.08504437,0.06094465,-0.04967562,-0.03952412,0.08680104,0.08532675,0.02700019,-0.09265205,-0.0101648,0.02849085,-0.01373461,0.04815419,-0.02242634,-0.01738377,-0.02157497,0.00323838,-0.04513604,-0.00762644,-0.00900301,-0.00726251,0.02187583,-0.01501468,0.02121145,0.02044858,-0.00486589,0.02435931,-0.00185783,0.00215943,0.00426391,-0.08395792,-0.06592037,0.00971162,0.06894311,-0.07206935,0.01112479,0.00206852,0.05372926,-0.03186749,-0.0289584,-0.04739274,-0.0160958,0.07206108,-0.00287179,0.00762863,-0.02315477,-0.02106486,-0.00778268,-0.00320758,0.0857105,0.11518896,-0.04439512,-0.01579651,0.00024519,-0.03171683,-0.00571409,-0.01165522,-0.00107333,0.01289379,0.02722771,0.03610967,0.02967296,0.03039186,-0.02735385,0.00738633,0.06540865,0.02137031,-0.01047391,0.04483251,0.04767898,0.04491001,-0.00725349,-0.00514832,0.0148884,0.02937294,-0.00407134,0.02616265,0.09112255,0.04544104,-0.01785864,-0.0160074,-0.05929376,-0.0251215,0.05221584,-0.04569032,0.05387019,0.00083748,7.435e-05,-0.03301236,0.06188389,-0.02536836,-0.0246115,-2.757e-05,0.01104674,0.03874201,-0.03768336,-0.01812873,-0.02621033,-0.02657681,-0.02202088,0