INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('88278e58-00d5-4ecf-aec7-fe83df531018','md-weight-loss-common-pitfalls','Common Pitfalls

- Too aggressive a deficit: below 1200 cal (women) or 1500 cal (men) causes muscle loss, fatigue, and rebound
- Ignoring protein: losing weight without protein = losing muscle, not fat
- All-or-nothing thinking: one bad meal is not failure. The next meal is the reset button.
- Overestimating exercise: 30 min of running burns ~250-300 calories — one cookie replaces it','Coheren Domain KB — Weight Loss','{"skill-progression","health"}','{"common","pitfalls","aggressive","deficit","below","1200","women","1500","causes","muscle","loss","fatigue","rebound","ignoring","protein"}','[-0.02430752,-0.00413862,-0.05134466,0.04470107,-0.02504082,-0.04002697,-0.12282843,-0.00749979,-0.09796308,0.03700655,-0.11152995,-0.0448757,-0.11081073,0.02286468,0.06276319,0.09842421,0.09653575,0.07246629,-0.02371305,-0.07019851,-0.0305033,-0.03172566,0.03866409,0.04258329,0.00617869,-0.11340996,-0.05102206,-0.0876257,-0.05846563,0.01787168,0.042524,-0.00594034,-0.05151216,0.03429333,0.0370606,-0.01329879,0.13041812,0.11072262,0.02258636,0.03867039,-0.00349424,0.07729848,0.04615816,-0.07974669,0.04291729,-0.0200306,0.0272501,-0.04295475,0.01672111,-0.08484514,-0.07996762,0.03678213,-0.02892539,0.03525479,-0.06581612,-0.00631813,0.0004186,0.01532695,-0.04105188,-0.01602179,-0.01389556,-0.04458899,0.03143295,-0.02887493,0.00446386,-0.07072485,-0.0340957,0.04146231,-0.00825141,0.00296343,0.08030622,-0.00214577,0.04885957,0.02317383,-0.02087305,0.00188524,-0.00172084,0.00554779,0.0174993,0.14871207,-0.02515898,-0.00101182,-0.0548656,-0.05009781,0.01122433,0.03159185,0.02014073,0.03802005,-0.03772891,0.03877889,0.00597103,0.06520087,0.01096173,-0.05173065,0.03524217,0.00257712,0.01624357,-0.00595942,0.01185111,0.00389877,-0.02839078,0.03725601,0.0151669,-0.06555868,-0.00846939,-0.04572999,0.07147186,-0.01275979,-0.02862558,-0.02637256,-4.944e-05,0.01101038,0.04989579,-0.0023283,-0.01935265,0.11373883,0.01616705,-0.03638311,-0.00671791,0.00359506,-0.0541849,-0.01342392,0.04356834,0.04658771,0.07760378,-0.03828617,0.05018464,0.01087492,-0.01355112,0.03158801,0.06007413,-0.00966461,0.02838579,0.02433583,0.02812696,-0.01316723,0.04849391,0.00974454,0.0063529,-0.06852186,-0.04536014,0.04418834,0.0390565,-0.03882331,-0.04454097,-0.02657913,0.03359427,0.00775165,-0.00307782