INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('bbcbb605-4497-4d28-96d4-72ab7d75f8b9','md-morning-routine-common-pitfalls','Common Pitfalls

- Adding too many elements at once: a 90-minute morning routine on week 1 is almost always abandoned by week 3
- Perfect or nothing: missing one day and abandoning the entire routine is the #1 failure mode
- Social media first: checking social media in the first 30 minutes puts you in reactive mode for the entire day
- Not adjusting for reality: the routine should serve your life, not be a rigid performance','Coheren Domain KB — Morning Routine','{"skill-progression","lifestyle"}','{"common","pitfalls","adding","many","elements","once","90-minute","morning","routine","week","almost","always","abandoned","perfect","nothing"}','[0.03731248,0.00457414,-0.00462684,0.03770518,-0.00889619,-0.02837993,-0.1312944,0.09906076,0.00621218,-0.05765263,-0.11209431,-0.07922745,-0.04870051,0.01593355,0.13647278,0.06683026,0.03787795,0.01286403,-0.00017021,-0.00193159,-0.07354039,-0.04892784,-0.02999567,0.05846931,0.01640009,-0.0929651,0.0034208,-0.0570697,-0.08428441,-0.00843456,0.05966202,-0.01483917,-0.00728733,0.03226644,0.00102004,-0.00036625,0.11437966,0.13762355,0.06676746,0.01982781,0.00183151,0.08110837,-0.00869237,0.0212925,0.00048683,-0.03006919,0.04503551,0.0188566,0.06464538,-0.098685,-0.06659994,0.07558601,0.0231558,-0.04722549,-0.03415664,-0.03193683,0.05346994,-0.03993255,0.06348015,-0.01472715,0.00664209,0.04864543,0.00572737,-0.02660194,-0.07320006,-0.06151741,-0.01814743,0.02711771,-0.07393712,0.03690049,0.08508285,0.02395801,0.05754188,0.01865344,-0.01473424,-0.02293496,-0.04247602,-0.04826862,-0.00250861,0.06268132,-0.03577254,-0.00309325,0.10140397,-0.02108221,0.0120366,0.04040122,-0.0365021,0.01700066,0.00936209,0.04980361,-0.02319914,0.03193304,-0.02602287,-0.08272401,0.03731596,0.01786091,0.04588854,-0.08854137,0.02897368,0.02691459,-0.00317669,-0.01175886,0.01078804,-0.04318156,0.03486823,0.01233952,0.10478952,-0.02698531,0.00637503,0.06299989,-0.01712728,-0.00424141,0.03041082,-0.04172032,-0.03156203,0.05737504,0.04750142,-0.06904735,0.02829716,0.04869051,-0.10190847,-0.02755148,0.03665248,0.05245782,0.05127111,-0.0297586,-0.00682852,-0.03905985,0.01299022,0.03778388,-0.03561709,0.03687078,-0.01593303,0.0866714,0.03582863,0.0123336,0.00830325,-0.03380103,0.03824942,0.00331447,0.00496924,0.01977585,0.05723081,-0.04963931,-0.04898523,-0.04755682,-0.01396419,0.00895828,-0