INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('0f120b79-9a8f-4171-995a-fa6887339f72','md-martial-arts-common-pitfalls','Common Pitfalls

- Brawling in sparring: Ego causes injury. Technical sparring is the goal — not fighting.
- Skipping footwork: Power without footwork is just pushing. Footwork generates angles and power.
- Dropping guard after punching: Every punch must return to guard before the next one starts.
- Training without drilling: Random bag hitting builds bad habits. Structured drilling builds muscle memory.','Coheren Domain KB — Martial Arts','{"skill-progression","kinesthetic"}','{"common","pitfalls","brawling","sparring","causes","injury","technical","goal","fighting","skipping","footwork","power","without","just","pushing"}','[0.05203019,-0.06787673,0.01145754,0.00646102,0.03384202,0.03688797,-0.02944934,0.10871046,-0.00452757,0.0461854,-0.03512843,-0.03380757,-0.04064635,0.03377606,0.18253845,0.06284055,0.02330072,-0.12118232,-0.03713217,0.01550964,-0.04122474,0.05130384,-0.04763104,0.06832313,0.05465996,-0.16846694,-0.05873854,-0.01540984,-0.04108633,-0.01012094,0.08702221,0.08243337,-0.03450556,0.01571824,-0.02863208,-0.07457133,0.09199715,0.05377382,-0.02281101,-0.00315449,-0.03095809,0.03333177,-0.01546711,-0.03195345,-0.00696428,-0.02091302,0.09639353,-0.02179572,0.03564986,-0.14266142,-0.04321689,-0.02248695,0.06355686,-0.03977161,-0.07592148,-0.00438059,0.02200383,0.0864969,0.1231325,-0.02504896,-0.0468939,0.04565906,-0.04321804,-0.00677214,-0.05587057,-0.03677643,-0.08181947,-0.0162353,-0.04113916,0.00915317,0.07023845,0.05832882,0.00582691,-0.0145191,0.03583807,-0.02258411,0.01360236,-0.06940498,-0.0260445,-0.00040092,-0.04519655,-0.01198021,0.0890484,-0.08989023,0.008161,0.1096013,0.03874785,0.05230229,0.01576105,0.02232244,-0.01208161,-0.01636219,-0.00866522,-0.01550591,0.02252899,0.00229575,-0.00248992,0.01669448,0.02823412,-0.0018443,-0.05214475,-0.03161076,0.0040127,-0.07282966,0.00100167,-0.00346403,0.11501853,-0.02364512,-0.01544603,0.04299642,0.04524499,-0.00470953,0.0620831,-0.05396428,-0.046616,0.0220724,0.03868667,-0.07945001,-0.0128665,-0.00743098,-0.09075602,0.03515154,0.03213707,0.04177625,0.02309031,-0.01936528,0.02287317,-0.06241331,-0.03185574,0.01840837,-0.03139332,-0.05964657,-0.04708,-0.0042847,0.01942991,-0.01041017,-0.02393805,-0.00301211,0.02909797,-0.06470407,0.01257156,0.02478976,0.08132333,-0.09024282,-0.03988588,-0.0575526