INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('bc8fb06a-9b41-4aa3-9073-8d44f33fcf15','md-running-common-pitfalls','Common Pitfalls

- Running too fast: Most beginner runs should feel embarrassingly slow
- Skipping rest days: Adaptation happens during rest, not during runs
- Comparing pace: Your 5K time is irrelevant. Consistency is the only metric that matters in Phase 1.
