INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('2fbffef4-f88b-462e-a03a-7222097eb298','md-strength-training-common-pitfalls','Common Pitfalls

- Ego lifting: Using weight you can''t control. Form breaks = injury waiting to happen.
- Not tracking: If you don''t track, you don''t progress. Every set, every rep.
- Skipping legs: Squat and deadlift release more growth hormone than any upper body lift. Leg day is non-negotiable.
- Inconsistency: 3 mediocre consistent months beats 3 perfect weeks. Show up even on bad days.
- Cardio timing: Never do intense cardio before strength training. Do it after, or on separate days.','Coheren Domain KB — Strength Training','{"skill-progression","kinesthetic"}','{"common","pitfalls","lifting","using","weight","can''t","control","form","breaks","injury","waiting","happen","tracking","don''t","track"}','[0.01298409,-0.01294103,-0.02445001,0.02882234,-0.01675486,-0.01227715,-0.07060718,0.04041015,0.01565898,-0.02326461,-0.05586189,-0.08354191,-0.07169054,0.02366387,0.22383194,0.06703258,0.00126519,-0.04867528,0.01324871,0.00235798,-0.05231608,-0.00067893,0.00466032,0.05689377,0.03142861,-0.08772816,-0.03702382,-0.01891175,-0.05539475,-0.03110762,0.06714284,0.07662,0.07465129,0.02668134,-0.03411341,-0.06995291,0.07537405,0.11723629,-0.00262501,0.03509649,-0.04611095,0.05433274,0.00202842,-0.0050753,0.00291622,-0.00120065,0.10476907,-0.01537139,0.03356016,-0.04150933,-0.03762955,0.00318331,0.02085385,-0.01687107,-0.04268081,-0.00625516,-0.02343641,-0.03564571,0.09491891,-0.0157582,0.01973786,0.06408376,-0.03771341,0.01398515,-0.05061897,-0.04423454,-0.0310925,0.00603956,-0.07942736,0.03596953,0.17153166,0.08221231,0.04848867,0.02047145,0.01269804,-0.00870328,-0.02302117,-0.068942,-0.01989055,0.05195356,-0.06343435,-0.0053626,0.06201244,-0.05108934,0.03639305,0.0435825,0.0158716,0.01109191,-0.00897474,0.11760542,-0.00572554,-0.01171245,-0.01966134,-0.05506901,0.03212015,0.01936912,0.00172282,-0.01764031,0.02454537,0.04824291,-0.03735963,-0.055261,-0.03626087,-0.1037738,-0.02700023,0.02198252,0.11246941,-0.01949946,0.01369418,-0.02028354,-0.03623203,-0.023964,0.00466533,-0.02507523,-0.03685854,-0.00422735,0.05391762,-0.06983041,-0.00500026,0.0261656,-0.08583371,-0.04122955,0.03206849,0.00972074,0.073638,0.03577916,-0.01069431,-0.0659695,-0.04849501,-0.01548594,-0.03476758,-0.00124832,-0.04252516,4.935e-05,0.02904757,-0.04203689,0.0016226,-0.00814401,0.02774018,-0.01561189,-0.04456468,-0.00433024,0.0598033,-0.04943627,-0.05439853,-0.06386006,-0.01443258,