INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('54e94f09-a9ed-4eae-b2e6-b26d1560fc8b','md-social-skills-common-pitfalls','Common Pitfalls

- Reading about social skills instead of practicing: social skill is only built through repetition in actual social situations
- Expecting instant results: social confidence builds through accumulated successful experiences over months
- Avoiding discomfort: every awkward conversation is practice — awkwardness is not failure
- Performing rather than connecting: trying to be impressive vs. trying to understand creates fake interactions','Coheren Domain KB — Social Skills','{"skill-progression","lifestyle"}','{"common","pitfalls","reading","about","social","skills","instead","practicing","skill","only","built","through","repetition","actual","situations"}','[0.05746654,-0.07708895,0.07193211,-0.03783165,0.07286356,0.02593259,-0.06783637,0.07763144,0.0292704,0.03773862,0.00172446,-0.14079379,0.03449366,0.073613,0.15169117,0.04613706,-0.00631123,-0.02704852,0.0283968,0.02080435,-0.02728389,0.03717512,0.00416612,-0.00952344,0.06600349,-0.16498417,-0.04022156,-0.0458604,-0.06056602,-0.03675266,0.13343337,-0.01792103,-0.03957329,0.06230549,0.03266899,-0.05109078,0.03856984,0.03416895,0.02582376,0.04686948,-0.04873949,0.05964475,0.02966441,0.02688405,-0.00213214,0.05046201,0.10675407,-0.02483926,0.05011604,-0.05149625,-0.01096829,0.0021387,0.00565294,0.03658155,-0.02911442,-0.03960354,0.09017906,-0.01294243,0.08667842,0.00826467,-0.01890634,0.07832039,-0.02702035,-0.00459407,-0.0438518,-0.01247866,-0.02516523,0.00637459,-0.10612723,0.02271127,0.09615071,0.04620657,-0.02981973,0.02465875,-0.00316622,-0.04685409,-0.02742006,-0.03024091,-0.01050441,0.02706799,-0.02392005,-0.03257032,0.09587947,-0.06217695,0.04407278,-0.00826623,0.00470606,0.02026722,-0.00473225,0.06082532,-0.06388059,-0.01785078,-0.03427541,0.02166703,-0.00853383,0.00463548,0.04434172,-0.00167166,0.0918434,0.01023617,-0.0177541,0.00198109,-0.06254903,-0.08705219,-0.00570112,0.00939953,0.03878561,-0.03058741,0.023195,0.01012644,-0.06188119,0.0319152,0.04602955,-0.05169364,-0.04100464,0.03393785,0.02467615,-0.04059587,-0.04105285,0.03125737,-0.08085921,-0.02714908,0.0027125,0.04170939,0.03321581,-0.01552719,-0.09280576,-0.02660597,0.0158519,0.05044546,-0.05652425,0.00424525,-0.01367597,0.05170511,0.03118199,-0.0110907,-0.03193561,-0.0943182,-0.00679787,-0.04488922,-0.0151156,-0.01108835,0.05879752,-0.07540726,-0.06083536,-0.11119158