INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('4c5fba3d-a07b-469f-96ec-e6765e877bcd','raptor_l1_Atomic_Habits_c1','The core insight shared across these passages is that lasting behavior change and habit formation require a strategic approach that leverages psychological principles. The Four Laws of Behavior Change, as outlined by James Clear, provide a framework for making desired behaviors obvious, attractive, easy, and satisfying. Key findings include the importance of starting small with the Two-Minute Rule, leveraging existing habits through Habit Stacking, and focusing on identity-based change rather than outcomes. The 1% Rule highlights the power of incremental improvement, demonstrating that small, consistent efforts can lead to remarkable results over time.','Atomic Habits (summary)','{"habit-formation","behavior-change","beginner","mindset","motivation"}','{"obvious","attractive","easy","satisfying","atomic","laws","two-minute","tiny","small","start","beginner","stacking","anchor","after","link","chain","identity","become","type of person","belief","compound","percent","better","growth","patience"}','[0.04552138,0.02496016,0.03155143,0.00324218,-0.04593487,-0.06599321,-0.01722369,0.11411676,0.02576388,-0.08170001,-0.07961347,0.02550185,-0.00626384,0.1270153,0.12179154,0.02921652,0.04290072,-0.01651319,-0.00990019,-0.13712339,-0.03439825,0.03424105,0.00908927,0.08423442,0.01335325,-0.07746568,0.0089992,-0.0768769,-0.06432962,-0.02524337,0.04554214,0.01168538,-0.00736826,0.06888652,0.08321512,0.00647878,0.04626244,0.0588107,0.040964,-0.02802028,0.09976622,0.05128644,-0.11261752,-0.01667698,0.01993242,0.04601657,0.08692966,-0.01595193,0.05154663,-0.07151877,0.01641936,0.09120901,-0.03069658,0.01869544,-0.08997833,-0.00330444,0.0551318,-0.03