INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('89facae1-1191-43b0-8937-bff170c01eb7','raptor_l1_The_Brain_That_Changes_Itself_c1','The core insight shared across these passages is that the brain''s neural pathways can be strengthened and reorganized through repetition and experience, a concept known as neuroplasticity. This idea is rooted in the work of neuroscientists such as Donald Hebb, who famously stated "neurons that fire together wire together." The most actionable finding for habit coaching is that repetition is key to strengthening neural pathways, and that habits can be intentionally shaped and reinforced through consistent practice. By leveraging factors that enhance neuroplasticity, such as sleep, exercise, meditation, and morning sunlight, individuals can optimize their brain''s ability to adapt and change, ultimately making it easier to form and maintain new habits.','The Brain That Changes Itself (summary)','{"neuroscience"}','{"neuroplasticity","brain","rewire","sleep","exercise","bdnf"}','[0.07323477,-0.04518488,-0.04045312,-0.0291121,0.00384252,0.00098919,-0.0345121,0.06258427,0.0141573,-0.03543913,-0.0644743,0.01987487,-0.03141531,0.13640042,0.12383062,0.10585397,-0.02407465,-0.09299546,0.01045928,-0.00538636,-0.05324661,0.04239086,-0.04582045,0.1811701,-0.02671136,-0.01893807,0.01651838,-0.12477998,-0.05943503,-0.09643339,0.03554827,0.04242487,-0.03806667,0.0503932,0.08765657,-0.02180488,0.05569249,-0.02844205,-0.01197791,-0.08049934,0.0318949,0.06424501,-0.09325361,0.04481736,0.03538112,0.07904356,0.07923624,-0.05447895,0.01340054,-0.04830971,0.02541721,0.15910187,-0.03171679,-0.06154973,-0.07291082,0.00938472,-0.00196764,0.0037487,0.00660385,-0.00862787,0.0276632,-0.02102072,-0.00113016,0.09220815,0.04001889,0.03252113,-0.00