INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('199be283-0237-4f3f-98cc-46634ec1bbbb','raptor_l1_Tiny_Habits___Atomic_Habits_c1','The core insight shared across these passages is that motivation is an unreliable driver of behavior change, and instead, individuals should focus on creating an environment that facilitates action. This approach is rooted in the theory of "habit formation" and the work of researchers such as Charles Duhigg, who identified the cue-routine-reward loop as a key component of habit formation. The most actionable finding for habit coaching is the importance of breaking down large tasks into smaller, manageable steps (the "2-minute rule") and making the cue for action more obvious, thereby increasing the likelihood of initiation and maintenance of new behaviors.','Tiny Habits + Atomic Habits (summary)','{"struggling","motivation"}','{"motivation","unmotivated","tired","lazy"}','[0.034969,-0.03952584,0.04452194,-0.04993196,-0.02692228,-0.0964677,-0.05118788,0.12049887,0.00871147,-0.03503661,-0.10487936,0.0213919,0.01040912,0.10496452,0.12152244,0.08494054,0.0247245,0.00342105,-0.03619987,-0.04481295,-0.06891169,-0.00927367,0.01401758,0.10263057,-0.02222405,-0.08410665,0.05787364,-0.08961062,-0.0480958,-0.09680901,0.04529949,0.05995907,-0.04653651,0.11245758,0.0287093,0.01203223,-0.00949395,0.06631822,-0.00350882,0.00829339,0.04455477,0.03361634,-0.07447565,-0.01435639,0.04056703,0.09057062,0.06041155,-0.03016046,0.02793895,-0.07736974,-0.05277143,0.07892403,-0.00596424,0.01175737,-0.03957823,0.02802094,0.112231,-0.07485915,0.04120718,-0.0704565,0.03720278,-0.05947142,-0.02446618,-0.00492914,0.02387415,-0.03856237,-0.01329179,0.0169037,-0.07792273,-0.02846107,0.08550175,0.02781213,0.01268559,-0.02140716,-0.03096638,-0.00546033,