INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('676761f6-3b1b-4412-830a-b811031fefd7','raptor_l1_motivational_interviewing_c2','Motivational Interviewing, a framework developed by William R. Miller and Stephen Rollnick, highlights the importance of language patterns in assessing an individual''s readiness for change. The theory suggests that specific linguistic cues, such as high hedge density, short answers to emotional questions, elaborate complaints about scheduling, passive voice clusters, and vague references to past attempts, can signal underlying issues like perfectionism, fear of failure, time constraints, inconsistency, and external locus of control. These language patterns can be used by coaches to identify potential obstacles to change and tailor their approach accordingly. The most actionable finding for habit coaching is to probe for explanations when clients mention past failures, as this can reveal underlying patterns and facilitate a more effective change process.','motivational-interviewing (summary)','{"habit-formation"}','{"application","coaching","stone","profiling","high","hedgedensity","answers","guess","maybe","sort","sustain","talk","dominance","readiness","short"}','[0.07463872,-0.09449954,0.05821889,0.02780199,0.00746147,-0.1131096,-0.07274004,0.11398884,0.07529593,-0.0820922,-0.12620422,0.05218885,0.02022355,0.08434474,0.10734169,0.09896056,0.02677815,-0.03939484,-0.07035463,0.02787485,-0.09664384,0.00549189,0.03428233,-0.06231109,0.03405178,-0.04092909,0.06561022,-0.02783544,-0.05261087,-0.02595937,0.06044761,0.00299815,-0.07173006,0.08641947,0.02537419,0.01815195,0.06706754,0.05770747,-0.04248592,-0.05358277,0.01128244,0.02659142,-0.05302004,0.05450048,-0.02825409,0.04558491,-0.0488635,0.01295479,0.10685343,-0.05703204