INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('7a612464-603e-47c0-aea1-85fc5ea26d64','raptor_l1_Tiny_Habits__BJ_Fogg__c1','The core insight shared across these passages is that effective habit formation relies on designing behaviors that are tiny, reliable, and emotionally rewarding. The key theory referenced is the B=MAP Formula, which highlights the importance of Ability and Prompt in facilitating behavior. The most actionable finding for habit coaching is to focus on creating tiny habits that can be done even on low-motivation days, using the Tiny Habit Recipe and leveraging the power of celebration to create a positive emotional association. By making habits feel easy and natural, individuals can trust the compound growth of tiny behaviors, which can eventually lead to lasting changes.','Tiny Habits (BJ Fogg) (summary)','{"habit-formation","beginner","behavior-change"}','{"tiny","habit","recipe","formula","after","anchor","moment","behavior","existing","reliably","happens","scaled","seconds","less","motivation","ability","prompt","three","must","converge","simultaneously","occur","compensate","each","other","highly","motivated","celebration","shine","feeling","immediate","positive","emotion","completing","most","powerful","tool","formation","victory","unreliable","fluctuates","wildly","mood","sleep","stress","circumstances","designing","habits","depend","high","guarantees","failure","low-motivation","growing","naturally","force","growth","feels","easy","natural","grow","metaphor","garden","plant","seeds"}','[0.02217343,-0.00828733,0.06491542,-0.00605158,0.01900389,-0.06456964,-0.04217511,0.10334269,0.02887823,-0.07380083,-0.10571642,0.03698528,-0.06032587,0.10442671,0.08369792,0.05782054,-0.05924051,-0.02145313,0.00886507,-0.05484889,-0.08818