INSERT INTO knowledge_chunks (id, chunk_id, content, source, categories, keywords, embedding, enriched_content, framework, content_type, applicable_stones, coaching_stage, evidence_level, emotion_context, chunk_type, raptor_level, raptor_source_ids, created_at) VALUES ('546b415b-9d50-428b-aa41-305762b5bc36','raptor_l1_sweller_cognitive_load_c2','The core insight shared across these passages is that instructional design should be tailored to the learner''s level of expertise and working memory capacity to minimize cognitive load. This is rooted in the Cognitive Load Theory (CLT) framework, which was developed by John Sweller and his colleagues. A key finding for habit coaching is that novices learn better from worked examples and isolated components, while experts benefit from independent problem-solving and complex systems. To apply this in habit coaching, coaches should consider breaking down complex habits into simpler components, providing personalized scaffolding, and using worked examples to facilitate schema formation. This can help reduce extraneous load and promote more effective learning and habit formation.','sweller-cognitive-load (summary)','{"habit-formation"}','{"effects","instructional","design","worked","example","effect","novices","learn","significantly","better","studying","examples","watching","solution","solving","cognitive","load","time","pressure","timeconstraint","learners","face","compound","problem","short","sessions","reduce","total","working","memory"}','[0.03605436,0.01314403,0.04595639,0.02590402,-0.00666993,-0.04644533,-0.07780134,0.08765823,0.00998267,-0.11644314,-0.05742582,-0.02039168,-0.04269205,0.10425542,0.14407548,0.10073864,-0.03917619,-0.03901374,-0.05487454,-0.00136097,-0.15799008,0.02041961,0.00387952,0.11900526,-0.00843791,-0.09828134,-0.0643072,-0.11998764,0.00195114,-0.06246746,0.08973808,0.036089,-0.02671079,0.05981216,0.04862848,-0.06919332,0.09443715,0.05271341,0.00428849,-0.03261199,0.04746109,0.07017767,-0.04286795,-0